import SwiftUI

/// What is in the app, and what each part is licensed under, generated by the build. It is a
/// screen, not a link, since going online would be a request the app otherwise never makes.
struct LicencesView: View {
    @EnvironmentObject private var store: WalletStore

    var body: some View {
        ScreenFrame(
            heading: Heading(number: "06", title: "Licences"),
            failure: store.state.failure,
            onDismissFailure: store.dismissFailure,
            onBack: { store.show(.ready) },
            status: Status.of(store.state),
            backdrop: .settings
        ) {
            Lead(text: "Generated from what the build linked, so it is what the app holds.")
            LazyVStack(alignment: .leading, spacing: 4) {
                ForEach(Licences.all, id: \.self) { entry in
                    line(entry)
                }
                Label(text: "Notices")
                    .padding(.top, Room.gap)
                ForEach(Licences.texts, id: \.self) { text in
                    line(text)
                        .padding(.bottom, Room.gap)
                }
            }
            .frame(maxWidth: .infinity, alignment: .leading)
        }
    }

    private func line(_ text: String) -> some View {
        Text(text)
            .font(.value(12))
            .lineSpacing(4)
            .foregroundStyle(Palette.darkMuted)
            .fixedSize(horizontal: false, vertical: true)
    }
}
